    return True


def ref(inp):
    (ha, wa, A), (hb, wb, B), (hx, wx, X) = _parse(inp)
    A_b = _blacks(A)
    B_b = _blacks(B)
    X_b = _blacks(X)
    # Window is fixed at origin; try every placement of A and B.
    for ra in range(-ha, hx + 1):
        for ca in range(-wa, wx + 1):
            pa = {(i + ra, j + ca) for (i, j) in A_b}
            for rb in range(-hb, hx + 1):
                for cb in range(-wb, wx + 1):
                    pb = {(i + rb, j + cb) for (i, j) in B_b}
                    if (pa | pb) == X_b:
                        return "Yes"
    return "No"
